    height: auto;
    aspect-ratio: 16 / 9;
    display: block;
    background: #16202a;
    box-shadow: 0 20px 80px rgba(0, 0, 0, 0.6);
    cursor: crosshair;
  }
  /* Read aloud, never shown: the status line screen readers announce. */
  #status { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }
</style>
</head>
