<div id="wrap">
  <canvas id="game" width="1280" height="720" aria-label="Salt Harbor: an open-world crime game. Walk with WASD, aim and shoot with the mouse, take a car with E."></canvas>
</div>
<p id="status" role="status" aria-live="polite">Salt Harbor. Press Enter to start.</p>
<script>
  // A module that fails leaves a blank canvas: keep the reason where a person (or a headless
  // run) can read it instead of guessing.
  window.addEventListener('error', function (event) {
    document.body.setAttribute('data-error', String(event.message) + ' @ ' + String(event.filename) + ':' + String(event.lineno));
  });
  window.addEventListener('unhandledrejection', function (event) {
    document.body.setAttribute('data-error', 'promise: ' + String(event.reason && event.reason.message ? event.reason.message : event.reason));
  });
</script>
<script type="module" src="./src/main.js"></script>
</body>
