  const ay = input.axisY();
  const speed = input.sprint() ? PLAYER.sprint : PLAYER.walk;
  const length = Math.hypot(ax, ay);
  const tx = length > 0 ? (ax / length) * speed : 0;
  const ty = length > 0 ? (ay / length) * speed : 0;
