export function damagePlayer(world, amount) {
  const player = world.player;
  if (player.dead) return;
  player.health -= amount;
  player.hurt = 0.3;
  if (player.health <= 0) {
    player.health = 0;
    player.dead = true;
    player.deadTimer = 2.6;
    player.respawns += 1;
    world.money = Math.max(0, world.money - 150);
    if (player.car) {
      player.car.driver = 'parked';
      player.car = null;
    }
  }
}
